  if (skipFunction(F))
    return false;
  auto *DT = &amp;getAnalysis&lt;DominatorTreeWrapperPass&gt;().getDomTree();
  auto *LI = &amp;getAnalysis&lt;LoopInfoWrapperPass&gt;().getLoopInfo();
  auto *TLI = &amp;getAnalysis&lt;TargetLibraryInfoWrapperPass&gt;().getTLI(F);
  auto GetTTI = [this](Function &amp;F) -&gt; TargetTransformInfo &amp; {
    return this-&gt;getAnalysis&lt;TargetTransformInfoWrapperPass&gt;().getTTI(F);
  };
  SeparateConstOffsetFromGEP Impl(DT, LI, TLI, GetTTI, LowerGEP);
  return Impl.run(F);
}

bool SeparateConstOffsetFromGEP::run(Function &amp;F) {
  if (DisableSeparateConstOffsetFromGEP)   // ​这里​直接​跳过​此​函数​
    return false;

  DL = &amp;F.getParent()-&gt;getDataLayout();
  bool Changed = false;
  for (BasicBlock &amp;B : F) {
    if (!DT-&gt;isReachableFromEntry(&amp;B))
      continue;

    for (Instruction &amp;I : llvm::make_early_inc_range(B))
      if (GetElementPtrInst *GEP = dyn_cast&lt;GetElementPtrInst&gt;(&amp;I))
        Changed |= splitGEP(GEP);
    // No need to split GEP ConstantExprs because all its indices are constant
    // already.
  }

  Changed |= reuniteExts(F);

  if (VerifyNoDeadCode)
    verifyNoDeadCode(F);

  return Changed;
}
