  /// explaining the match failure.
  virtual bool MatchAndEmitInstruction(SMLoc IDLoc, unsigned &amp;Opcode,
                                       OperandVector &amp;Operands, MCStreamer &amp;Out,
                                       uint64_t &amp;ErrorInfo,
