using namespace cv;
using namespace std;

int main() {
    // ​启用​ OpenCL ​支持​
    cv::ocl::setUseOpenCL(true);

    // ​检查​ OpenCL ​是否​成功​启用​
    if (cv::ocl::haveOpenCL()) {
        std::cout &lt;&lt; "OpenCL is supported and enabled." &lt;&lt; std::endl;
        // ​可​选​：​打印​可用​的​ OpenCL ​设备​信息​
        cv::ocl::Device device = cv::ocl::Device::getDefault();
        std::cout &lt;&lt; "Using OpenCL device: " &lt;&lt; device.name() &lt;&lt; std::endl;
    } else {
        std::cout &lt;&lt; "OpenCL is not supported or failed to initialize." &lt;&lt; std::endl;
        // ​程序​可以​继续​在​ CPU ​上​运行​
    }

    // ---------------------- 1. ​读取​图像​ ----------------------
    // ​请​确保​这​两张​图片​文件​与​可执行文件​在​同一​目录​下​，​或者​提供​完整​路径​
    Mat img1 = imread("query.png", IMREAD_GRAYSCALE);  // ​查询​图​（​灰度​图​）
    Mat img2 = imread("train.png", IMREAD_GRAYSCALE);  // ​训练​图​（​灰度​图​）

    if (img1.empty() || img2.empty()) {
        cout &lt;&lt; "​错误​：​无法​读取​图像​，​请​检查​图像​路径​和​文件名​是否​正确​！" &lt;&lt; endl;
        return -1;
    }

    // ---------------------- 2. ​初始化​ ORB ​特征​检测器​ ----------------------
    // ​参数​顺序​和​类型​严格​遵循​ OpenCV 4.2 ​的​ API ​文档​
    Ptr&lt;ORB&gt; orb = ORB::create(
        500,                    // nfeatures: ​最大​特征​点​数量​
        1.2f,                   // scaleFactor: ​尺度​因子​
        8,                      // nlevels: ​金字塔​层数​
        31,                     // edgeThreshold: ​边缘​阈值​
        0,                      // firstLevel: ​第一个​金字塔​层​
        2,                      // WTA_K: ​用于​计算​描述​子​的​点​对​数量​
        ORB::HARRIS_SCORE,      // scoreType: ​评分​函数​类型​
        31,                     // patchSize: ​计算​描述​子​的​补丁​大小​
        20                      // fastThreshold: FAST ​角点​检测​阈值​
    );

    // ---------------------- 3. ​提取​特征​点​和​描述​子​ ----------------------
    vector&lt;KeyPoint&gt; kp1, kp2;  // ​存储​关键点​
    Mat des1, des2;             // ​存储​描述​子​ (ORB ​生成​的​是​ 32 ​位​二进制​描述​子​)

//    orb-&gt;detectAndCompute(img1, Mat(), kp1, des1);  // ​提取​查询​图​的​特征​
//    orb-&gt;detectAndCompute(img2, Mat(), kp2, des2);  // ​提取​训练​图​的​特征​

    UMat uimg1, uimg2;
    img1.copyTo(uimg1);
    img2.copyTo(uimg2);

    // ​提取​特征​时​使用​UMat
    orb-&gt;detectAndCompute(uimg1, UMat(), kp1, des1);
    orb-&gt;detectAndCompute(uimg2, UMat(), kp2, des2);

    cout &lt;&lt; "​查询​图​检测​到​的​特征​点​数量​：" &lt;&lt; kp1.size() &lt;&lt; endl;
    cout &lt;&lt; "​训练​图​检测​到​的​特征​点​数量​：" &lt;&lt; kp2.size() &lt;&lt; endl;

    // ---------------------- 4. ​方案​1：BF ​暴力​匹配​ ----------------------
    // ORB ​描述​子​是​二进制​的​，​因此​使用​汉明​距离​ (NORM_HAMMING) ​进行​匹配​
    BFMatcher bf_matcher(NORM_HAMMING, true); // true ​表示​启用​交叉​验证​，​匹配​更​稳定​
    vector&lt;DMatch&gt; bf_matches;
    bf_matcher.match(des1, des2, bf_matches);  // ​执行​匹配​

    // ​使用​ Ratio Test ​筛选​出​优质​匹配​
    double min_dist = 1e9;
    for (const auto&amp; m : bf_matches) {
        if (m.distance &lt; min_dist) min_dist = m.distance;
    }
    vector&lt;DMatch&gt; good_bf_matches;
    for (const auto&amp; m : bf_matches) {
        // ​设定​一个​合理​的​阈值​，​这里​使用​ 2 * min_dist ​或​ 30.0 ​中​的​较大​值​
        if (m.distance &lt;= max(2.0 * min_dist, 30.0)) {
            good_bf_matches.push_back(m);
        }
    }

    cout &lt;&lt; "BF ​匹配​后​筛选​出​的​优质​特征​点​数量​：" &lt;&lt; good_bf_matches.size() &lt;&lt; endl;

    // ---------------------- 5. ​方案​2：FLANN ​快速​匹配​ ----------------------
    // ​对于​大规模​特征​点​匹配​，FLANN ​比​ BF ​匹配​快得多​
    // ​为​二进制​描述​子​配置​ FLANN ​参数​
    Ptr&lt;flann::IndexParams&gt; index_params = makePtr&lt;flann::LshIndexParams&gt;(6, 12, 1);
    Ptr&lt;flann::SearchParams&gt; search_params = makePtr&lt;flann::SearchParams&gt;(50); // checks=50

    FlannBasedMatcher flann_matcher(index_params, search_params);
    vector&lt;vector&lt;DMatch&gt;&gt; flann_matches;
    // ​使用​ k-NN ​匹配​，k=2，​即​每个​查询​点​返回​两个​最佳​匹配​
    flann_matcher.knnMatch(des1, des2, flann_matches, 2);

    // ​使用​ Ratio Test ​筛选​优质​匹配​
    vector&lt;DMatch&gt; good_flann_matches;
    for (const auto&amp; m_n : flann_matches) {
        // ​如果​最佳​匹配​的​距离远​小于​次佳​匹配​的​距离​，​则​认为​是​一个​好​的​匹配​
        if (m_n[0].distance &lt; 0.75 * m_n[1].distance) {
            good_flann_matches.push_back(m_n[0]);
        }
    }

    cout &lt;&lt; "FLANN ​匹配​后​筛选​出​的​优质​特征​点​数量​：" &lt;&lt; good_flann_matches.size() &lt;&lt; endl;
#if 0
    // ---------------------- 6. ​可视化​匹配​结果​ ----------------------
    Mat bf_match_img, flann_match_img;

    // --- ​方案​一​：​使用​最​简洁​的​ drawMatches ​调用​ ---
    // ​只​提供​必要​的​参数​，​颜色​和​绘制​选项​使用​默认值​，​避免​参数​不​匹配​问题​
    drawMatches(img1, kp1, img2, kp2, good_bf_matches, bf_match_img);
