    printf("​找到​ %d ​个​ OpenCL ​平台​\n", ret_num_platforms);

    // ​获取​平台​名称​
    char platform_name[128];
    clGetPlatformInfo(platform_id, CL_PLATFORM_NAME, sizeof(platform_name), platform_name, NULL);
    printf("​平台​名称​: %s\n", platform_name);

    char platform_version[128];
    clGetPlatformInfo(platform_id, CL_PLATFORM_VERSION, sizeof(platform_version), platform_version, NULL);
    printf("​平台​版本​: %s\n", platform_version);

    // 2. ​获取​设备​
    ret = clGetDeviceIDs(platform_id, CL_DEVICE_TYPE_DEFAULT, 1, &amp;device_id, &amp;ret_num_devices);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​获取​设备​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }
    printf("​找到​ %d ​个​ OpenCL ​设备​\n", ret_num_devices);

    // ​获取​设备​名称​
    char device_name[128];
    clGetDeviceInfo(device_id, CL_DEVICE_NAME, sizeof(device_name), device_name, NULL);
    printf("​设备​名称​: %s\n", device_name);

    // 3. ​创建​上下文​
    context = clCreateContext(NULL, 1, &amp;device_id, NULL, NULL, &amp;ret);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​创建​上下文​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }
    printf("OpenCL ​上下文​创建​成功​\n");

    // 4. ​创建​命令​队列​
    command_queue = clCreateCommandQueueWithProperties(context, device_id, NULL, &amp;ret);
    if (ret != CL_SUCCESS) {
        // ​尝试​使用​旧版​ API (OpenCL 1.x)
        command_queue = clCreateCommandQueue(context, device_id, 0, &amp;ret);
    }
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​创建​命令​队列​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }
    printf("​命令​队列​创建​成功​\n");

    // 5. ​创建​缓冲区​对象​
    d_A = clCreateBuffer(context, CL_MEM_READ_ONLY, 
                         VECTOR_SIZE * sizeof(float), NULL, &amp;ret);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​创建​缓冲区​ A ​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }

    d_B = clCreateBuffer(context, CL_MEM_READ_ONLY,
                         VECTOR_SIZE * sizeof(float), NULL, &amp;ret);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​创建​缓冲区​ B ​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }

    d_C = clCreateBuffer(context, CL_MEM_WRITE_ONLY,
                         VECTOR_SIZE * sizeof(float), NULL, &amp;ret);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​创建​缓冲区​ C ​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }
    printf("​设备​缓冲区​创建​成功​\n");

    // 6. ​将​数据传输​到​设备​
    ret = clEnqueueWriteBuffer(command_queue, d_A, CL_TRUE, 0,
                               VECTOR_SIZE * sizeof(float), h_A, 0, NULL, NULL);
    ret |= clEnqueueWriteBuffer(command_queue, d_B, CL_TRUE, 0,
                                VECTOR_SIZE * sizeof(float), h_B, 0, NULL, NULL);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​数据传输​到​设备​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }
    printf("​数据​已​传输​到​设备​\n");

    // 7. ​创建​程序​对象​
    program = clCreateProgramWithSource(context, 1, &amp;kernelSource, NULL, &amp;ret);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​创建​程序​对象​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }

    // 8. ​编译程序​
    ret = clBuildProgram(program, 1, &amp;device_id, NULL, NULL, NULL);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​编译程序​失败​! ​错误代码​: %d\n", ret);

        // ​获取​编译​日志​
        size_t log_size;
        clGetProgramBuildInfo(program, device_id, CL_PROGRAM_BUILD_LOG, 0, NULL, &amp;log_size);
        char *log = (char*)malloc(log_size);
        clGetProgramBuildInfo(program, device_id, CL_PROGRAM_BUILD_LOG, log_size, log, NULL);
        printf("​编译​日志​:\n%s\n", log);
        free(log);
        return -1;
    }
    printf("​内核​程序​编译​成功​\n");

    // 9. ​创建​内核​对象​
    kernel = clCreateKernel(program, "vector_add", &amp;ret);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​创建​内核​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }
    printf("​内核​对象​创建​成功​\n");

    // 10. ​设置​内核​参数​
    unsigned int vector_size = VECTOR_SIZE;
    ret = clSetKernelArg(kernel, 0, sizeof(cl_mem), (void *)&amp;d_A);
    ret |= clSetKernelArg(kernel, 1, sizeof(cl_mem), (void *)&amp;d_B);
    ret |= clSetKernelArg(kernel, 2, sizeof(cl_mem), (void *)&amp;d_C);
    ret |= clSetKernelArg(kernel, 3, sizeof(unsigned int), (void *)&amp;vector_size);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​设置​内核​参数​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }
    printf("​内核​参数设置​成功​\n");

    // 11. ​执行​内核​
    size_t global_work_size = VECTOR_SIZE;
    size_t local_work_size = 64;  // ​工作组​大小​

    printf("​执行​内核​计算​...\n");
    ret = clEnqueueNDRangeKernel(command_queue, kernel, 1, NULL,
                                 &amp;global_work_size, &amp;local_work_size, 0, NULL, NULL);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​执行​内核​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }

    // 12. ​读取​结果​
    ret = clEnqueueReadBuffer(command_queue, d_C, CL_TRUE, 0,
                              VECTOR_SIZE * sizeof(float), h_C, 0, NULL, NULL);
    if (ret != CL_SUCCESS) {
        printf("​错误​: ​读取​结果​失败​! ​错误代码​: %d\n", ret);
        return -1;
    }
    printf("​结果​已​从​设备​读取​\n");

    // 13. ​验证​结果​
    printf("\n​验证​结果​...\n");
    int errors = 0;
    for(int i = 0; i &lt; VECTOR_SIZE; i++) {
        float expected = h_A[i] + h_B[i];
        if (h_C[i] != expected) {
            if (errors &lt; 10) {  // ​只​打印​前​10​个​错误​
                printf("​错误​ [%d]: ​期望​ %.2f, ​实际​ %.2f\n", i, expected, h_C[i]);
            }
            errors++;
        }
    }

    if (errors == 0) {
        printf("✓ ​验证​成功​! ​所有​ %d ​个​元素​计算​正确​\n", VECTOR_SIZE);
        printf("\n​示例​结果​ (​前​10​个​元素​):\n");
        for(int i = 0; i &lt; 10; i++) {
            printf("  %.2f + %.2f = %.2f\n", h_A[i], h_B[i], h_C[i]);
        }
    } else {
        printf("✗ ​验证​失败​! ​发现​ %d ​个​错误​\n", errors);
    }

    // 14. ​清理​资源​
    clFlush(command_queue);
    clFinish(command_queue);
    clReleaseKernel(kernel);
    clReleaseProgram(program);
    clReleaseMemObject(d_A);
    clReleaseMemObject(d_B);
    clReleaseMemObject(d_C);
    clReleaseCommandQueue(command_queue);
    clReleaseContext(context);

    free(h_A);
    free(h_B);
    free(h_C);

    printf("\n​程序执行​完毕​!\n");
    return 0;
}
</code></pre>

