"                         __global const float *B,\n"
"                         __global float *C,\n"
"                         const unsigned int n)\n"
"{\n"
"    int i = get_global_id(0);\n"
"    if (i &lt; n) {\n"
"        C[i] = A[i] + B[i];\n"
"    }\n"
"}\n";

void print_compilation_path(const char *method) {
    printf("\n" "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n");
    printf("​编译​方法​: %s\n", method);
    printf("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n");
}

