        printf("  - ​需要​预先​生成​ SPIR-V ​文件​\n");
        printf("  - ​使用​ llvm-spirv ​工具​转换​\n");
        printf("  - ​支持​特化​常量​ (Specialization Constants)\n");
        printf("  - ​适合​跨平台​二进制​分发​\n");

        printf("\n​离线​生成​ SPIR-V ​的​步骤​:\n");
        printf("  $ clang -cl-std=CL2.0 -emit-llvm -c kernel.cl -o kernel.bc\n");
        printf("  $ llvm-spirv kernel.bc -o kernel.spv\n");
        printf("  # ​然后​在​程序​中​:\n");
        printf("  # cl_program prog = clCreateProgramWithIL(ctx, spirv_data, size, &amp;err);\n");
    }

