};
</code></pre> <p>counter​对象​的​目地​就是​用来​申请​一个​块内存​来存​引用​基数​，s​是​share_ptr​的​引用​计数​，w​是​weak_ptr​的​引用​计数​，​当​w​为​0​时​，​删除​Counter​对象​。</p>

C++<pre><code>template &lt;class T&gt;
class WeakPtr; //​为了​用​weak_ptr​的​lock()，​来​生成​share_ptr​用​，​需要​拷贝​构造​用​

template &lt;class T&gt;
class SharePtr
{
public:
    SharePtr(T *p = 0) : _ptr(p)
    {
        cnt = new Counter();
        if (p)
            cnt-&gt;s = 1;
        cout &lt;&lt; "in construct " &lt;&lt; cnt-&gt;s &lt;&lt; endl;
    }
    ~SharePtr()
    {
        release();
    }

    SharePtr(SharePtr&lt;T&gt; const &amp;s)
    {
        cout &lt;&lt; "in copy con" &lt;&lt; endl;
        _ptr = s._ptr;
        (s.cnt)-&gt;s++;
        cout &lt;&lt; "copy construct" &lt;&lt; (s.cnt)-&gt;s &lt;&lt; endl;
        cnt = s.cnt;
    }
    SharePtr(WeakPtr&lt;T&gt; const &amp;w) //​为了​用​weak_ptr​的​lock()，​来​生成​share_ptr​用​，​需要​拷贝​构造​用​
    {
        cout &lt;&lt; "in w copy con " &lt;&lt; endl;
        _ptr = w._ptr;
        (w.cnt)-&gt;s++;
        cout &lt;&lt; "copy w  construct" &lt;&lt; (w.cnt)-&gt;s &lt;&lt; endl;
        cnt = w.cnt;
    }
    SharePtr&lt;T&gt; &amp;operator=(SharePtr&lt;T&gt; &amp;s)
    {
        if (this != &amp;s)
        {
            release();
            (s.cnt)-&gt;s++;
            cout &lt;&lt; "assign construct " &lt;&lt; (s.cnt)-&gt;s &lt;&lt; endl;
            cnt = s.cnt;
            _ptr = s._ptr;
        }
        return *this;
    }
    T &amp;operator*()
    {
        return *_ptr;
    }
    T *operator-&gt;()
    {
        return _ptr;
    }
    friend class WeakPtr&lt;T&gt;; //​方便​weak_ptr​与​share_ptr​设置​引用​计数​和​赋值​

protected:
    void release()
    {
        cnt-&gt;s--;
        cout &lt;&lt; "release " &lt;&lt; cnt-&gt;s &lt;&lt; endl;
        if (cnt-&gt;s &lt; 1)
        {
            delete _ptr;
            if (cnt-&gt;w &lt; 1)
            {
                delete cnt;
                cnt = NULL;
            }
        }
    }

private:
    T *_ptr;
    Counter *cnt;
};
</code></pre> <p>share_ptr​的​给出​的​函数​接口​为​：​构造​，​拷贝​构造​，​赋值​，​解​引用​，​通过​release​来​在​引用​计数​为​0​的​时候​删除​_ptr​和​cnt​的​内存​。</p>

C++<pre><code>template &lt;class T&gt;
class WeakPtr
{
public: //​给出​默认​构造​和​拷贝​构造​，​其中​拷贝​构造​不能​有​从​原始​指针​进行​构造​
    WeakPtr()
    {
        _ptr = 0;
        cnt = 0;
    }
    WeakPtr(SharePtr&lt;T&gt; &amp;s) : _ptr(s._ptr), cnt(s.cnt)
    {
        cout &lt;&lt; "w con s" &lt;&lt; endl;
        cnt-&gt;w++;
    }
    WeakPtr(WeakPtr&lt;T&gt; &amp;w) : _ptr(w._ptr), cnt(w.cnt)
    {
        cnt-&gt;w++;
    }
    ~WeakPtr()
    {
        release();
    }
    WeakPtr&lt;T&gt; &amp;operator=(WeakPtr&lt;T&gt; &amp;w)
    {
        if (this != &amp;w)
        {
            release();
            cnt = w.cnt;
            cnt-&gt;w++;
            _ptr = w._ptr;
        }
        return *this;
    }
    WeakPtr&lt;T&gt; &amp;operator=(SharePtr&lt;T&gt; &amp;s)
    {
        cout &lt;&lt; "w = s" &lt;&lt; endl;
        release();
        cnt = s.cnt;
        cnt-&gt;w++;
        _ptr = s._ptr;
        return *this;
    }
    SharePtr&lt;T&gt; lock()
    {
        return SharePtr&lt;T&gt;(*this);
    }
    bool expired()
    {
        if (cnt)
        {
            if (cnt-&gt;s &gt; 0)
            {
                cout &lt;&lt; "empty" &lt;&lt; cnt-&gt;s &lt;&lt; endl;
                return false;
            }
        }
        return true;
    }
    friend class SharePtr&lt;T&gt;; //​方便​weak_ptr​与​share_ptr​设置​引用​计数​和​赋值​

protected:
    void release()
    {
        if (cnt)
        {
            cnt-&gt;w--;
            cout &lt;&lt; "weakptr release" &lt;&lt; cnt-&gt;w &lt;&lt; endl;
            if (cnt-&gt;w &lt; 1 &amp;&amp; cnt-&gt;s &lt; 1)
            {
                //delete cnt;
                cnt = NULL;
            }
        }
    }

private:
    T *_ptr;
    Counter *cnt;
};
</code></pre> <p>weak_ptr​一般​通过​share_ptr​来​构造​，​通过​expired​函数​检查​原始​指针​是否​为空​，lock​来​转化​为​share_ptr。</p>

C++<pre><code>#include &lt;iostream&gt;
using namespace std;

class Base
{
public :
    int base_data;
    Base() { base_data = 1; }
    virtual void func1() { cout &lt;&lt; "base_func1" &lt;&lt; endl; }
    virtual void func2() { cout &lt;&lt; "base_func2" &lt;&lt; endl; }
    virtual void func3() { cout &lt;&lt; "base_func3" &lt;&lt; endl; }
};

class Derive : public Base
{
public :
    int derive_data;
    Derive() { derive_data = 2; }
    virtual void func1() { cout &lt;&lt; "derive_func1" &lt;&lt; endl; }
    virtual void func2() { cout &lt;&lt; "derive_func2" &lt;&lt; endl; }
};

typedef void (*func)();

int main()
{
    Base base;
    cout &lt;&lt; "&amp;base: " &lt;&lt; &amp;base &lt;&lt; endl;
    cout &lt;&lt; "&amp;base.base_data: " &lt;&lt; &amp;base.base_data &lt;&lt; endl;
    cout &lt;&lt; "----------------------------------------" &lt;&lt; endl;

    Derive derive;
    cout &lt;&lt; "&amp;derive: " &lt;&lt; &amp;derive &lt;&lt; endl;
    cout &lt;&lt; "&amp;derive.base_data: " &lt;&lt; &amp;derive.base_data &lt;&lt; endl;
    cout &lt;&lt; "&amp;derive.derive_data: " &lt;&lt; &amp;derive.derive_data &lt;&lt; endl;
    cout &lt;&lt; "----------------------------------------" &lt;&lt; endl;

    for(int i=0; i&lt;3; i++)
    {
        // &amp;base : base​首​地址​
        // (unsigned long*)&amp;base : base​的​首​地址​，vptr​的​地址​
        // (*(unsigned long*)&amp;base) : vptr​的​内容​，​即​vtable​的​地址​，​指向​第一个​虚​函数​的​slot​的​地址​
        // (unsigned long*)(*(unsigned long*)&amp;base) : vtable​的​地址​，​指向​第一个​虚​函数​的​slot​的​地址​
        // vtbl : ​指向​虚​函数​slot​的​地址​
        // *vtbl : ​虚​函数​的​地址​
        unsigned long* vtbl = (unsigned long*)(*(unsigned long*)&amp;base) + i;
        cout &lt;&lt; "slot address: " &lt;&lt; vtbl &lt;&lt; endl;
        cout &lt;&lt; "func address: 0x" &lt;&lt; hex &lt;&lt; *vtbl &lt;&lt; endl;
        func pfunc = (func)*(vtbl);
        pfunc();
        cout &lt;&lt; endl;
    }
    cout &lt;&lt; "----------------------------------------" &lt;&lt; endl;

    for(int i=0; i&lt;3; i++)
    {
        unsigned long* vtbl = (unsigned long*)(*(unsigned long*)&amp;derive) + i;
        cout &lt;&lt; "slot address: " &lt;&lt; vtbl &lt;&lt; endl;
        cout &lt;&lt; "func address: 0x" &lt;&lt; hex &lt;&lt; *vtbl &lt;&lt; endl;
        func pfunc = (func)*(vtbl);
        pfunc();
        cout &lt;&lt; endl;
    }
    cout &lt;&lt; "----------------------------------------" &lt;&lt; endl;
    return 1;
}
