      hash(pcurrentFunc_currentPass_IR) == hash(currentFunc_currentPass_IR)?) then (yes)
    : ​设置​isEffective = 0;
  else (no)
    : ​设置​isEffective = 1;
  endif
  : ​更新​map(currentFunc, currentPass)​为​
    &lt;hash(pcurrentFunc_currentPass_IR)，hash(currentFunc_currentPass_IR), isEffective&gt;;
  stop
endif
@enduml
